import{_ as a,o as r,c as o,a2 as l}from"./chunks/framework.BbQrW5_t.js";const q=JSON.parse('{"title":"第七章：模型后训练 - 核心知识笔记","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/07-chapter7.md","filePath":"study/ai-agent-book/07-chapter7.md","lastUpdated":1785465991000}'),i={name:"study/ai-agent-book/07-chapter7.md"};function e(n,t,s,d,h,g){return r(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="第七章-模型后训练-核心知识笔记" tabindex="-1">第七章：模型后训练 - 核心知识笔记 <a class="header-anchor" href="#第七章-模型后训练-核心知识笔记" aria-label="Permalink to &quot;第七章：模型后训练 - 核心知识笔记&quot;">​</a></h1><hr><h2 id="一、核心框架-三阶段训练范式" tabindex="-1">一、核心框架：三阶段训练范式 <a class="header-anchor" href="#一、核心框架-三阶段训练范式" aria-label="Permalink to &quot;一、核心框架：三阶段训练范式&quot;">​</a></h2><h3 id="_1-1-预训练-→-sft-→-rl-的递进关系" tabindex="-1">1.1 预训练 → SFT → RL 的递进关系 <a class="header-anchor" href="#_1-1-预训练-→-sft-→-rl-的递进关系" aria-label="Permalink to &quot;1.1 预训练 → SFT → RL 的递进关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>数据</th><th>优化目标</th><th>学到什么</th><th>典型代价</th></tr></thead><tbody><tr><td><strong>预训练</strong></td><td>海量互联网文本</td><td>预测下一个词</td><td>语言规律、世界知识、基本推理</td><td>极高（数千万美元）</td></tr><tr><td><strong>SFT</strong></td><td>几千～几万条&quot;输入—输出&quot;示范对</td><td>预测下一个词（只在回答上算损失）</td><td>指令遵循、输出格式、风格、流程协议</td><td>低（几小时～几天）</td></tr><tr><td><strong>RL</strong></td><td>任务 + 奖励函数（无标准答案）</td><td>最大化期望奖励</td><td>可迁移的决策策略、探索出的新解法</td><td>高（SFT的几十～上百倍）</td></tr></tbody></table><p><strong>直觉类比</strong>：</p><ul><li>预训练 = 读万卷书（积累知识）</li><li>SFT = 老师手把手教标准解法（模仿示范）</li><li>RL = 自己下场做题、根据对错反复打磨（试错提升）</li></ul><h3 id="_1-2-为什么必须先-sft-后-rl" tabindex="-1">1.2 为什么必须先 SFT 后 RL？ <a class="header-anchor" href="#_1-2-为什么必须先-sft-后-rl" aria-label="Permalink to &quot;1.2 为什么必须先 SFT 后 RL？&quot;">​</a></h3><p>RL 不看标准答案，而是让模型自己生成回答再给奖惩。要判断好坏，首先得能把模型输出解析出来。</p><p><strong>SFT 的角色</strong>：先把&quot;形&quot;（格式、结构）立起来，RL 再追求&quot;神&quot;（策略、泛化）——<strong>先形后神</strong>。</p><p><strong>边界条件</strong>：足够强的基础模型可以跳过 SFT 直接 RL（如 DeepSeek-R1-Zero），但代价是输出可读性差、语言混杂。</p><hr><h2 id="二、核心主线一-sft-记忆-rl-泛化" tabindex="-1">二、核心主线一：SFT 记忆，RL 泛化 <a class="header-anchor" href="#二、核心主线一-sft-记忆-rl-泛化" aria-label="Permalink to &quot;二、核心主线一：SFT 记忆，RL 泛化&quot;">​</a></h2><h3 id="_2-1-本质区别" tabindex="-1">2.1 本质区别 <a class="header-anchor" href="#_2-1-本质区别" aria-label="Permalink to &quot;2.1 本质区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>SFT</th><th>RL</th></tr></thead><tbody><tr><td>优化目标</td><td>最大化标注答案的概率（极大似然）</td><td>最大化期望奖励</td></tr><tr><td>训练信号</td><td>唯一的标准答案</td><td>自己生成的多条回答 + 奖励</td></tr><tr><td>学到的东西</td><td>固定的&quot;输入→输出&quot;映射（<strong>记忆</strong>）</td><td>可迁移的决策策略（<strong>泛化</strong>）</td></tr><tr><td>分布漂移下</td><td>环境一变就套用旧答案、性能下降</td><td>用同一策略重新求解、更稳</td></tr></tbody></table><h3 id="_2-2-为什么-rl-上限更高" tabindex="-1">2.2 为什么 RL 上限更高？ <a class="header-anchor" href="#_2-2-为什么-rl-上限更高" aria-label="Permalink to &quot;2.2 为什么 RL 上限更高？&quot;">​</a></h3><p>RL 是&quot;在线&quot;方法，带来三个好处：</p><ol><li><strong>离线的天花板是数据，在线的天花板是任务</strong>：SFT 最多逼近示范者水平；RL 能发现示范里不存在的更优策略。</li><li><strong>验证比生成容易</strong>：数学题答案能对照、代码能跑测试——只要&quot;认出好&quot;比&quot;做出好&quot;容易，RL 就能训出比任何现成示范者都强的模型。</li><li><strong>练在自己会走的路上</strong>：训练时走的就是部署时会走的分布，每一步反馈都精确打在当前真实弱点上。</li></ol><h3 id="_2-3-mode-seeking-vs-mass-covering" tabindex="-1">2.3 Mode-Seeking vs Mass-Covering <a class="header-anchor" href="#_2-3-mode-seeking-vs-mass-covering" aria-label="Permalink to &quot;2.3 Mode-Seeking vs Mass-Covering&quot;">​</a></h3><ul><li><strong>SFT（极大似然）= Mass-Covering（覆盖式）</strong>：努力覆盖示范里出现的所有模式，&quot;雨露均沾&quot;。</li><li><strong>RL（带 KL 约束）= Mode-Seeking（寻峰）</strong>：找到少数几个奖励最高的峰，把概率集中过去，&quot;赢者通吃&quot;。</li></ul><hr><h2 id="三、核心主线二-数据与环境比算法更重要" tabindex="-1">三、核心主线二：数据与环境比算法更重要 <a class="header-anchor" href="#三、核心主线二-数据与环境比算法更重要" aria-label="Permalink to &quot;三、核心主线二：数据与环境比算法更重要&quot;">​</a></h2><h3 id="_3-1-优先级排序" tabindex="-1">3.1 优先级排序 <a class="header-anchor" href="#_3-1-优先级排序" aria-label="Permalink to &quot;3.1 优先级排序&quot;">​</a></h3><p><strong>先验（基础模型）&gt; 环境 &gt; 算法</strong></p><p>现成的 RL 算法（PPO、GRPO 等）你会用就够了，真正决定成败的是：</p><ul><li><strong>仿真环境的保真度</strong>（跟真实部署场景有多像）</li><li><strong>训练数据的质量</strong>（覆盖面、多样性、标注准确性）</li></ul><h3 id="_3-2-环境-模型练习的场地" tabindex="-1">3.2 环境：模型练习的场地 <a class="header-anchor" href="#_3-2-环境-模型练习的场地" aria-label="Permalink to &quot;3.2 环境：模型练习的场地&quot;">​</a></h3><ul><li><strong>环境失真，策略必废</strong>：仿真里的客服按固定套路回话、错误信息跟生产环境对不上，模型会学到一套只在仿真里管用的&quot;应试策略&quot;。</li><li><strong>构建高保真环境，常常比训练本身更贵、更难</strong>。</li><li><strong>环境的另一半是奖励函数</strong>。</li></ul><p><strong>造不出环境怎么办？让模型扮演环境</strong>：</p><ol><li>模型合成工具调用的返回值（如 ZeroSearch 用 LLM 扮演搜索引擎）</li><li>模型仿真整个环境的动态（如 DreamGym）</li></ol><p><strong>风险</strong>：模拟器的世界知识就是训练的天花板，系统性偏差会被策略照单全收。</p><h3 id="_3-3-数据-最关键的一环" tabindex="-1">3.3 数据：最关键的一环 <a class="header-anchor" href="#_3-3-数据-最关键的一环" aria-label="Permalink to &quot;3.3 数据：最关键的一环&quot;">​</a></h3><p><strong>铁律：数据质量胜过算法</strong></p><ul><li>SFT 会一字不差地把数据里的噪声和偏见固化进参数</li><li>RL 会朝着有偏差的奖励拼命优化，把错误方向越走越远</li></ul><p><strong>实用判断</strong>：很多场景下，只要 SFT 的数据质量到位，你根本不需要做 RL。</p><p><strong>数据质量三维度</strong>：</p><ol><li><strong>覆盖面</strong>：有没有覆盖到部署时会遇到的各种情况（尤其是长尾和边界情况）</li><li><strong>多样性</strong>：示范里的说话者、风格、解法够不够丰富</li><li><strong>标注准确性</strong>：示范答案本身对不对</li></ol><hr><h2 id="四、sft-监督微调" tabindex="-1">四、SFT（监督微调） <a class="header-anchor" href="#四、sft-监督微调" aria-label="Permalink to &quot;四、SFT（监督微调）&quot;">​</a></h2><h3 id="_4-1-本质" tabindex="-1">4.1 本质 <a class="header-anchor" href="#_4-1-本质" aria-label="Permalink to &quot;4.1 本质&quot;">​</a></h3><p>SFT 在数学上和预训练是同一个任务——都是预测下一个词。差别只有两点：</p><ol><li><strong>数据不同</strong>：用人工精心准备的&quot;输入—输出&quot;对</li><li><strong>损失只算在&quot;回答&quot;上</strong>（loss masking）</li></ol><h3 id="_4-2-lora-参数高效微调" tabindex="-1">4.2 LoRA 参数高效微调 <a class="header-anchor" href="#_4-2-lora-参数高效微调" aria-label="Permalink to &quot;4.2 LoRA 参数高效微调&quot;">​</a></h3><ul><li>不动原始大权重矩阵，只在旁边挂一个低秩矩阵（参数量仅占 1%-5%）</li><li><strong>实践经验</strong>： <ul><li>必须把 LoRA 应用到所有主要权重矩阵（尤其 MLP 层）</li><li>最优学习率约是全参微调的 10 倍</li><li>SFT 用中高 rank（64-256），RL 用小 rank（8-32）</li></ul></li></ul><h3 id="_4-3-sft-数据来源" tabindex="-1">4.3 SFT 数据来源 <a class="header-anchor" href="#_4-3-sft-数据来源" aria-label="Permalink to &quot;4.3 SFT 数据来源&quot;">​</a></h3><ol><li><strong>人工专家示范</strong>：质量天花板最高，但贵且慢</li><li><strong>教师模型生成</strong>：让强模型批量产出&quot;输入—输出&quot;对</li><li><strong>模型自举</strong>：拒绝采样微调（RFT），模型自己采样多条候选，用验证器筛出正确样本再训练自己</li></ol><h3 id="_4-4-何时选择-sft" tabindex="-1">4.4 何时选择 SFT <a class="header-anchor" href="#_4-4-何时选择-sft" aria-label="Permalink to &quot;4.4 何时选择 SFT&quot;">​</a></h3><ul><li>固化输出格式（JSON schema、API 调用格式）</li><li>固化协议性知识（术语用法、输出格式、流程习惯）</li><li>统一风格（语气、长度）</li></ul><p><strong>注意</strong>：SFT 不适合注入大量事实性知识——那需要继续预训练或 RAG。</p><hr><h2 id="五、rlhf-从人类偏好到奖励模型" tabindex="-1">五、RLHF：从人类偏好到奖励模型 <a class="header-anchor" href="#五、rlhf-从人类偏好到奖励模型" aria-label="Permalink to &quot;五、RLHF：从人类偏好到奖励模型&quot;">​</a></h2><h3 id="_5-1-instructgpt-三段式管线" tabindex="-1">5.1 InstructGPT 三段式管线 <a class="header-anchor" href="#_5-1-instructgpt-三段式管线" aria-label="Permalink to &quot;5.1 InstructGPT 三段式管线&quot;">​</a></h3><ol><li><strong>SFT</strong>：用人工示范的&quot;指令—回答&quot;对微调预训练模型</li><li><strong>训练奖励模型（RM）</strong>：人类标注员两两比较回答偏好，训练打分模型</li><li><strong>用 RM 打分做 PPO</strong>：以 RM 的分数作为奖励信号，对 SFT 模型做 PPO 训练</li></ol><h3 id="_5-2-kl-惩罚" tabindex="-1">5.2 KL 惩罚 <a class="header-anchor" href="#_5-2-kl-惩罚" aria-label="Permalink to &quot;5.2 KL 惩罚&quot;">​</a></h3><p>$$r = r_{\\text{RM}} - \\beta \\cdot \\mathrm{KL}\\big(\\pi_\\theta | \\pi_{\\text{ref}}\\big)$$</p><p><strong>四个关键点</strong>：</p><ol><li>KL 散度衡量两个概率分布的差异</li><li>方向是&quot;当前策略在前、参考策略在后&quot;（<strong>反向 KL</strong>）</li><li>反向 KL 是 <strong>mode-seeking</strong> 的——只保留少数几个高奖励的峰</li><li>目的是防止 <strong>reward hacking</strong> 和分布崩塌</li></ol><h3 id="_5-3-奖励模型过优化" tabindex="-1">5.3 奖励模型过优化 <a class="header-anchor" href="#_5-3-奖励模型过优化" aria-label="Permalink to &quot;5.3 奖励模型过优化&quot;">​</a></h3><p>随着 RL 训练推进，代理奖励（RM 分数）单调上升，而真实质量（人类评估）先升后降——模型学会的是&quot;让 RM 打高分&quot;，而非&quot;更好地回答&quot;。</p><h3 id="_5-4-dpo-跳过显式奖励模型" tabindex="-1">5.4 DPO：跳过显式奖励模型 <a class="header-anchor" href="#_5-4-dpo-跳过显式奖励模型" aria-label="Permalink to &quot;5.4 DPO：跳过显式奖励模型&quot;">​</a></h3><p>直接把偏好对变成带隐式奖励的分类损失，不需要在线采样、不需要价值网络、不需要单独维护 RM。</p><p><strong>代价</strong>：完全离线，无法探索偏好数据之外的新行为。</p><hr><h2 id="六、强化学习算法比较" tabindex="-1">六、强化学习算法比较 <a class="header-anchor" href="#六、强化学习算法比较" aria-label="Permalink to &quot;六、强化学习算法比较&quot;">​</a></h2><h3 id="_6-1-核心算法一览" tabindex="-1">6.1 核心算法一览 <a class="header-anchor" href="#_6-1-核心算法一览" aria-label="Permalink to &quot;6.1 核心算法一览&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>类型</th><th>核心思路</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>REINFORCE</strong></td><td>在线 RL</td><td>用整条轨迹的最终奖励来更新策略</td><td>理论基准</td></tr><tr><td><strong>PPO</strong></td><td>在线 RL</td><td>限制每次更新幅度，防止策略&quot;跑偏&quot;</td><td>多轮Agent、长轨迹信用分配</td></tr><tr><td><strong>GRPO</strong></td><td>在线 RL</td><td>组内相对比较&quot;哪条更好&quot;，无需价值网络</td><td>单轮/短轨迹任务</td></tr><tr><td><strong>DPO</strong></td><td>离线偏好优化</td><td>把偏好对直接变成带隐式奖励的分类损失</td><td>已有高质量偏好数据</td></tr><tr><td><strong>KTO</strong></td><td>离线偏好优化</td><td>仅需给单个样本打&quot;好/坏&quot;标签</td><td>标注资源极有限</td></tr></tbody></table><hr><h2 id="七、奖励信号设计" tabindex="-1">七、奖励信号设计 <a class="header-anchor" href="#七、奖励信号设计" aria-label="Permalink to &quot;七、奖励信号设计&quot;">​</a></h2><h3 id="_7-1-奖励密度谱" tabindex="-1">7.1 奖励密度谱 <a class="header-anchor" href="#_7-1-奖励密度谱" aria-label="Permalink to &quot;7.1 奖励密度谱&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>特点</th><th>适用场景</th></tr></thead><tbody><tr><td><strong>二元奖励</strong></td><td>成功=1，失败=0</td><td>有明确正确答案的任务（数学题、SQL查询）</td></tr><tr><td><strong>稀疏奖励</strong></td><td>只在最终结果给反馈</td><td>容易陷入大量无效探索</td></tr><tr><td><strong>过程奖励</strong></td><td>对执行中每个关键步骤给予即时反馈</td><td>降低长时序信用分配难度</td></tr></tbody></table><h3 id="_7-2-rlvp-奖励结果-约束过程" tabindex="-1">7.2 RLVP：奖励结果，约束过程 <a class="header-anchor" href="#_7-2-rlvp-奖励结果-约束过程" aria-label="Permalink to &quot;7.2 RLVP：奖励结果，约束过程&quot;">​</a></h3><p>$$R = O + \\beta\\cdot\\Phi$$</p><ul><li><strong>O</strong>：结果奖励（稀疏，是真正的目标）</li><li><strong>Φ</strong>：路径信号（确定性规则引擎逐动作给出）</li></ul><p><strong>四条设计原则</strong>：</p><ol><li>只惩罚可验证的&quot;动作&quot;，绝不惩罚&quot;没进展&quot;</li><li>结果奖励始终是主驱动力，惩罚不能单独优化</li><li>每个惩罚配一个对应的守规奖励</li><li>合规路径必须可达、惩罚靶子必须无法钻空子</li></ol><hr><h2 id="八、常见陷阱与最佳实践" tabindex="-1">八、常见陷阱与最佳实践 <a class="header-anchor" href="#八、常见陷阱与最佳实践" aria-label="Permalink to &quot;八、常见陷阱与最佳实践&quot;">​</a></h2><h3 id="_8-1-常见陷阱" tabindex="-1">8.1 常见陷阱 <a class="header-anchor" href="#_8-1-常见陷阱" aria-label="Permalink to &quot;8.1 常见陷阱&quot;">​</a></h3><ol><li>过度依赖后训练来记忆事实——应该用 RAG</li><li>格式未稳定就引入 RL——必须先做 SFT</li><li>奖励函数设计不当导致奖励黑客</li><li>忽视仿真保真度</li><li>过度训练导致泛化下降</li><li>价值函数崩溃与探索不足</li><li>低估 RL 的计算成本（可能是 SFT 的 10-100 倍）</li><li>训练数据质量低下</li></ol><h3 id="_8-2-核心原则" tabindex="-1">8.2 核心原则 <a class="header-anchor" href="#_8-2-核心原则" aria-label="Permalink to &quot;8.2 核心原则&quot;">​</a></h3><p><strong>在投入大规模资源前，先用小规模实验验证关键假设</strong></p><hr><h2 id="九、关键公式总结" tabindex="-1">九、关键公式总结 <a class="header-anchor" href="#九、关键公式总结" aria-label="Permalink to &quot;九、关键公式总结&quot;">​</a></h2><ol><li><p><strong>Bellman 方程</strong>：$Q^<em>(s, a) = r + \\gamma \\max_{a&#39;} Q^</em>(s&#39;, a&#39;)$</p></li><li><p><strong>KL 惩罚</strong>：$r = r_{\\text{RM}} - \\beta \\cdot \\mathrm{KL}\\big(\\pi_\\theta | \\pi_{\\text{ref}}\\big)$</p></li><li><p><strong>PPO 裁剪目标</strong>：$L^{\\text{CLIP}}(\\theta) = \\mathbb{E}\\Big[\\min\\big(\\rho,\\hat{A},\\ \\operatorname{clip}(\\rho,, 1-\\epsilon,, 1+\\epsilon),\\hat{A}\\big)\\Big]$</p></li><li><p><strong>GRPO 优势估计</strong>：$\\hat{A}_i = \\frac{r_i - \\operatorname{mean}(r_1,\\dots,r_N)}{\\operatorname{std}(r_1,\\dots,r_N)}$</p></li><li><p><strong>RLVP 总奖励</strong>：$R = O + \\beta\\cdot\\Phi$</p></li></ol><hr><h2 id="十、核心结论" tabindex="-1">十、核心结论 <a class="header-anchor" href="#十、核心结论" aria-label="Permalink to &quot;十、核心结论&quot;">​</a></h2><ol><li><p><strong>SFT 和 RL 不是竞争关系，而是先后关系</strong>：SFT 先把输出格式稳定下来，RL 再学会泛化。</p></li><li><p><strong>数据和环境比算法更重要</strong>：现成的 RL 算法你会用就行，真正拉开差距的是仿真环境的保真度和训练数据的质量。</p></li><li><p><strong>当前 RL 的主要瓶颈是样本效率</strong>：On-Policy Distillation 和 RLVP 是最有希望的两个方向。</p></li><li><p><strong>&quot;先形后神&quot;的训练范式</strong>：SFT 到&quot;格式稳定、能力初具&quot;即止，RL 在此基础上塑形策略。</p></li></ol><hr><p><strong>来源</strong>：《AI Agent 实战》第七章：模型后训练 <strong>核心论点</strong>：SFT 记忆、RL 泛化；数据与环境比算法更重要</p>',89)])])}const b=a(i,[["render",e]]);export{q as __pageData,b as default};
